-- Per-service database roles and grants
-- =========================================================================
-- GENERATED by scripts/gen-db-roles.js from src/platform/service-map.js.
-- Do not hand-edit: change the service map, then run `npm run db:roles`.
--
-- WHAT THIS DOES
--   Creates one login role per service and grants it USAGE and DML on ONLY the
--   schemas that service owns. A service touching a schema it does not own then
--   gets `42501 permission denied` from Postgres instead of a quietly wrong
--   answer. It makes `search_path` isolation enforced rather than conventional.
--
-- WHAT IT DOES NOT DO
--   No REVOKE, no DROP, no ALTER of an existing role, no schema change, no data
--   change. It is additive only, so it needs no rollback plan: nothing in the
--   application connects as these roles until a DATABASE_URL_<SERVICE> variable
--   is set, and unsetting that variable is the rollback.
--
-- RUN IT AS THE ROLE THAT RUNS MIGRATIONS
--   The ALTER DEFAULT PRIVILEGES statements below apply to tables created by
--   the role executing them. Migrations run as the database owner (`postgres`
--   on Supabase, which is also who the SQL editor runs as), so run this there.
--   Executed as anyone else, future tables will not inherit the grants and the
--   next migration will quietly produce tables the services cannot read.
--
-- ORDER
--   1. Run this file.
--   2. Set a password per role (see the end of this file). Never commit them.
--   3. Put the connection strings in DATABASE_URL_<SERVICE> for ONE service.
--   4. `npm run test:db-roles` — proves each role reaches its own schemas and
--      is refused on every other one.
--   5. Repeat 3-4 for the next service.
--
-- Dev first. Production only after dev passes step 4.
-- =========================================================================

BEGIN;


-- ── core          3 schema(s): identity, notify, work
-- ──────────────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_core') THEN
    CREATE ROLE svc_core LOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA extensions TO svc_core;
GRANT USAGE ON SCHEMA identity TO svc_core;
GRANT USAGE ON SCHEMA notify TO svc_core;
GRANT USAGE ON SCHEMA work TO svc_core;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA identity TO svc_core;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA identity TO svc_core;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA notify TO svc_core;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA notify TO svc_core;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA work TO svc_core;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA work TO svc_core;

-- Future tables and sequences, so the next migration does not have to remember.
ALTER DEFAULT PRIVILEGES IN SCHEMA identity GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_core;
ALTER DEFAULT PRIVILEGES IN SCHEMA identity GRANT USAGE, SELECT ON SEQUENCES TO svc_core;
ALTER DEFAULT PRIVILEGES IN SCHEMA notify GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_core;
ALTER DEFAULT PRIVILEGES IN SCHEMA notify GRANT USAGE, SELECT ON SEQUENCES TO svc_core;
ALTER DEFAULT PRIVILEGES IN SCHEMA work GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_core;
ALTER DEFAULT PRIVILEGES IN SCHEMA work GRANT USAGE, SELECT ON SEQUENCES TO svc_core;

-- ── hr            2 schema(s): people, workforce
-- ──────────────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_hr') THEN
    CREATE ROLE svc_hr LOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA extensions TO svc_hr;
GRANT USAGE ON SCHEMA people TO svc_hr;
GRANT USAGE ON SCHEMA workforce TO svc_hr;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA people TO svc_hr;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA people TO svc_hr;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA workforce TO svc_hr;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA workforce TO svc_hr;

-- Future tables and sequences, so the next migration does not have to remember.
ALTER DEFAULT PRIVILEGES IN SCHEMA people GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_hr;
ALTER DEFAULT PRIVILEGES IN SCHEMA people GRANT USAGE, SELECT ON SEQUENCES TO svc_hr;
ALTER DEFAULT PRIVILEGES IN SCHEMA workforce GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_hr;
ALTER DEFAULT PRIVILEGES IN SCHEMA workforce GRANT USAGE, SELECT ON SEQUENCES TO svc_hr;

-- ── defects       1 schema(s): defects
-- ──────────────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_defects') THEN
    CREATE ROLE svc_defects LOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA extensions TO svc_defects;
GRANT USAGE ON SCHEMA defects TO svc_defects;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA defects TO svc_defects;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA defects TO svc_defects;

-- Future tables and sequences, so the next migration does not have to remember.
ALTER DEFAULT PRIVILEGES IN SCHEMA defects GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_defects;
ALTER DEFAULT PRIVILEGES IN SCHEMA defects GRANT USAGE, SELECT ON SEQUENCES TO svc_defects;

-- ── files         1 schema(s): files
-- ──────────────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_files') THEN
    CREATE ROLE svc_files LOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA extensions TO svc_files;
GRANT USAGE ON SCHEMA files TO svc_files;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA files TO svc_files;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA files TO svc_files;

-- Future tables and sequences, so the next migration does not have to remember.
ALTER DEFAULT PRIVILEGES IN SCHEMA files GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_files;
ALTER DEFAULT PRIVILEGES IN SCHEMA files GRANT USAGE, SELECT ON SEQUENCES TO svc_files;

-- ── integrations  1 schema(s): integrations
-- ──────────────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'svc_integrations') THEN
    CREATE ROLE svc_integrations LOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA extensions TO svc_integrations;
GRANT USAGE ON SCHEMA integrations TO svc_integrations;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA integrations TO svc_integrations;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA integrations TO svc_integrations;

-- Future tables and sequences, so the next migration does not have to remember.
ALTER DEFAULT PRIVILEGES IN SCHEMA integrations GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO svc_integrations;
ALTER DEFAULT PRIVILEGES IN SCHEMA integrations GRANT USAGE, SELECT ON SEQUENCES TO svc_integrations;

COMMIT;

-- =========================================================================
-- VERIFY — read-only, run after the COMMIT above.
-- =========================================================================
-- Every service role, and the schemas it may use. Each role must show ONLY its
-- own schemas plus `extensions`.
SELECT r.rolname AS role,
       string_agg(n.nspname, ', ' ORDER BY n.nspname) AS usable_schemas
  FROM pg_roles r
  CROSS JOIN pg_namespace n
 WHERE r.rolname LIKE 'svc\_%'
   AND n.nspname NOT LIKE 'pg\_%'
   AND n.nspname <> 'information_schema'
   AND has_schema_privilege(r.rolname, n.nspname, 'USAGE')
 GROUP BY r.rolname
 ORDER BY r.rolname;

-- =========================================================================
-- PASSWORDS — not in this file, and not in git.
-- =========================================================================
-- Generate one per role, 32 bytes of randomness, and set it with:
--
--   ALTER ROLE svc_core PASSWORD '<paste one here>';
--
-- Generate them with:
--
--   node -e "console.log(require('crypto').randomBytes(24).toString('base64url'))"
--
-- Then build each connection string from the one DATABASE_URL already uses,
-- replacing only the user and password, and put it in DATABASE_URL_<SERVICE>.
--
-- These roles have LOGIN and no password until you do this, and a role with no
-- password cannot connect — so nothing is reachable by accident in between.
